SELECT ROUND((
  (SELECT COALESCE(SUM(amount), 0) FROM orders WHERE status IN ('paid','shipped','delivered') AND strftime('%Y-%m', created_at) = '2026-09') -
  (SELECT COALESCE(SUM(amount), 0) FROM orders WHERE status IN ('paid','shipped','delivered') AND strftime('%Y-%m', created_at) = '2026-08')
) * 100.0 / NULLIF((SELECT SUM(amount) FROM orders WHERE status IN ('paid','shipped','delivered') AND strftime('%Y-%m', created_at) = '2026-08'), 0), 2) AS mom_change_pct;

